<?php
namespace Modules\BankingCoreDeposits\Services;
use Illuminate\Support\Facades\DB; use Modules\BankingCoreDeposits\Entities\DepositAccount; use Modules\BankingCoreDeposits\Entities\DepositTransaction;
class DepositTransactionService { public function post(DepositAccount $account, array $data): DepositTransaction { return DB::transaction(function () use ($account, $data) { $amount = (float) $data['amount']; $creditTypes = ['deposit','transfer_in','interest']; $newBalance = in_array($data['type'], $creditTypes, true) ? $account->ledger_balance + $amount : $account->ledger_balance - $amount; $account->ledger_balance = $newBalance; $account->available_balance = $newBalance; $account->save(); return DepositTransaction::create(array_merge($data, ['account_id'=>$account->id, 'business_id'=>$account->business_id, 'location_id'=>$account->location_id, 'balance_after'=>$newBalance, 'transaction_no'=>$data['transaction_no'] ?? 'DTX-'.now()->format('ymdHis').'-'.random_int(100,999)])); }); } }
